329	// openNetdiagFromStatus is what H on a monitor does: netdiag is built prefilled
330	// with the monitor's target, and remembers status as the place to return to.
331	func openNetdiagFromStatus(t *testing.T, a *App, autoRun bool) *netdiag.Model {
332		t.Helper()
333		a.views[command.ViewStatus] = &fakeView{}
334		a.currentView = command.ViewStatus
335		a.Update(netdiag.OpenRequestMsg{Target: netcheck.Target{Host: "example.com", Port: 443}, AutoRun: autoRun})
336		held, ok := a.views[command.ViewNetdiag].(*netdiag.Model)
337		if !ok || held.OriginView != command.ViewStatus {
338			t.Fatalf("setup: netdiag %T with origin %v", a.views[command.ViewNetdiag], ok)
339		}
340		return held
341	}
342	
343	// Same shape as the security view: a diagnostic another view sent here is that
344	// view's detail. Naming netdiag asks for netdiag — a blank form — and re-entering
345	// it used to land on the same frozen prefill, whose origin then made esc leave
346	// for a monitor the new target had nothing to do with.
347	func TestNamingNetdiagAfterAnotherViewSentADiagnosticStartsAFreshForm(t *testing.T) {
348		a := router(t, &fakeView{})
349		held := openNetdiagFromStatus(t, a, false)
350	
351		enterNetdiagByCommand(t, a)
352	
353		fresh, ok := a.views[command.ViewNetdiag].(*netdiag.Model)
354		if !ok {
355			t.Fatalf("the installed view is %T", a.views[command.ViewNetdiag])
356		}
357		if fresh == held {
358			t.Error("the prefilled view was kept")
359		}
360		if fresh.OriginView != "" {
361			t.Errorf("OriginView = %q, want none: this is not a diagnostic status sent", fresh.OriginView)
362		}
363		if a.currentView != command.ViewNetdiag {
364			t.Errorf("current view = %s, want netdiag", a.currentView)
365		}
366	}
367	
368	// The run is the reason for the precaution: dropping the view would discard a
369	// diagnostic that is still walking its stages, with nothing said.
370	func TestNamingNetdiagDoesNotDropARunInFlight(t *testing.T) {
371		a := router(t, &fakeView{})
372		held := openNetdiagFromStatus(t, a, true)
373		if !held.Running() {
374			t.Fatal("setup: the diagnostic is not running")
375		}
376	
377		enterNetdiagByCommand(t, a)
378	
379		if a.views[command.ViewNetdiag].(*netdiag.Model) != held {
380			t.Error("a diagnostic in flight was thrown away")
381		}
382	}
383	
384	// Opened from the command line, netdiag has no origin and keeps its state across
385	// a switch, like any other view.
386	func TestNetdiagOpenedByNameKeepsItsState(t *testing.T) {
387		a := router(t, &fakeView{})
388		enterNetdiagByCommand(t, a)
389		first := a.views[command.ViewNetdiag].(*netdiag.Model)
390	
391		enterNetdiagByCommand(t, a)
392	
393		if a.views[command.ViewNetdiag].(*netdiag.Model) != first {
394			t.Error("a view with no origin was rebuilt")
395		}
396	}
