func (a *App) runCommand() (tea.Model, tea.Cmd) {
	input, ok := a.runnableText()
	if !ok {
		// Only a drawn list has a rule to carry the notice; without one the
		// refusal is silent, a documented exception to Rule 130.
		if a.listVisible() > 0 {
			a.sugNotice = a.nothingToRunNotice()
		}
		return a, nil
	}

	cmd := command.ParseCommand(input)

	switch cmd.Type {
	case command.CommandQuit:
		a.resetSuggestions()
		return a, tea.Quit

	case command.CommandView:
		a.commandMode = false
		a.commandInput.Blur()
		a.resetSuggestions()
		a.resetSelectionModeFor(cmd.View)
		return a, a.switchView(cmd.View)

	case command.CommandContext:
		return a.runContext(cmd.Args)
	}

	return a, nil
}

// resetSelectionModeFor takes a view out of selection mode before switching to
// it, by dropping it so it is rebuilt normally.
//
// Only the workspaces view is lent now. The images view was the other one — the
// security form borrowed it to pick a scan target — and it could not simply be
// dropped, because it holds scan results worth keeping; it took a
// ResetSelectionMsg instead. That whole path went with the form (phase 3).
//
// The security and network views are dropped too, when they are showing what
// another view sent them: workspaces and images set the security view's
// OriginView, and status's H sets netdiag's. What such a view shows is that
// view's detail, not its own state. Naming the view asks for the view — its
	// maxPaletteWidth caps the frame on wide terminals.
	maxPaletteWidth = 80
	// sideMargin is the cells left free on each side of a framed palette.
	sideMargin = 2
)

// Rect is where the palette sits on screen, in cells and rows. Rows is the
// number of suggestion rows; Height is the whole frame.
type Rect struct{ X, Y, Width, Height, Rows int }

// PaletteInput is everything RenderPalette needs.
type PaletteInput struct {
	Title string // "Go to" or "Contexts"
	Input string // the input line, already rendered by the caller
	List  Input  // rows, cursor, notice; Width and Visible are set from Rect
}

// PaletteRows returns the number of suggestion rows for v free lines: a
// constant of the geometry, independent of the number of matches.
func PaletteRows(v int) int {
	return max(min(MaxVisibleRows, v-paletteChrome), 0)
}

// Geometry places the palette for a width x height terminal whose header
// block is headerLines high and whose view footer is footerLines high. It
// never returns a negative field.
func Geometry(width, height, headerLines, footerLines int) Rect {
	width, height = max(width, 0), max(height, 0)
	headerLines, footerLines = max(headerLines, 0), max(footerLines, 0)

	rows := PaletteRows(height - headerLines - footerLines)
	h := reducedHeight
	if rows > 0 {
		h = rows + paletteChrome
	}
	w := width
	if width >= narrowWidth {
		w = min(width-2*sideMargin, maxPaletteWidth)
	}
	y := headerLines
	if y+h > height {
		// Pull up onto the blank line under the header; the rest is clipped.
