func TestThePaletteIsCenteredAndSized(t *testing.T) {
	cases := []struct{ width, wantX, wantW int }{
		{80, 2, 76},
		{53, 0, 53}, // under 54 columns: the full width
		{54, 2, 50},
		{120, 20, 80}, // capped at 80
		{200, 60, 80},
	}
